## Patrones de iteración avanzados

```javascript
// Desestructurar al iterar con índice:
const frutas = ['manzana', 'pera', 'uva'];
for (const [i, fruta] of frutas.entries()) {
  console.log(`${i}: ${fruta}`);
}

// Iterar múltiples arrays en paralelo (zip):
function* zip(...arrays) {
  const length = Math.min(...arrays.map(a => a.length));
  for (let i = 0; i < length; i++) {
    yield arrays.map(a => a[i]);
  }
}

const nombres = ['Ana', 'Bob', 'Carl'];
const edades  = [30, 25, 35];

for (const [nombre, edad] of zip(nombres, edades)) {
  console.log(`${nombre}: ${edad}`);
}
// 'Ana: 30', 'Bob: 25', 'Carl: 35'
```

