// Convertir Map a diferentes estructuras
const inventario = new Map([
  ['manzana', { stock: 100, precio: 1200 }],
  ['pera',    { stock: 50,  precio: 1500 }],
  ['uva',     { stock: 75,  precio: 2000 }],
]);

// A array de claves:
const productos = [...inventario.keys()];
console.log(productos); // ['manzana', 'pera', 'uva']

// A array de objetos:
const lista = Array.from(inventario, ([nombre, datos]) => ({
  nombre,
  ...datos,
}));
console.log(lista[0]); // { nombre: 'manzana', stock: 100, precio: 1200 }

// Total de stock con reduce:
const totalStock = [...inventario.values()]
  .reduce((sum, { stock }) => sum + stock, 0);
console.log('Stock total:', totalStock); // 225

// Patrón: tabla de frecuencias con Map + sort por valor
function topN(texto, n) {
  const freq = new Map();
  for (const palabra of texto.toLowerCase().split(' ')) {
    freq.set(palabra, (freq.get(palabra) ?? 0) + 1);
  }

  // Ordenar por frecuencia descendente, tomar los primeros N
  return [...freq.entries()]
    .sort(([, a], [, b]) => b - a)
    .slice(0, n)
    .map(([palabra, count]) => ({ palabra, count }));
}

const texto = 'el sol y la luna el sol brilla la luna ilumina el cielo';
const top3 = topN(texto, 3);
console.log(top3);
// [{palabra:'el',count:3},{palabra:'sol',count:2},{palabra:'la',count:2}]

