function rangoArray(inicio, fin) {
  return Array.from(
    { length: fin - inicio + 1 },
    (_, i) => inicio + i
  );
}

function mapAObjeto(map) {
  return Array.from(map, ([clave, valor]) => ({ clave, valor }));
}

