const ventas = [
  { vendedor: 'Ana',  producto: 'A', monto: 1000 },
  { vendedor: 'Bob',  producto: 'B', monto: 1500 },
  { vendedor: 'Ana',  producto: 'B', monto: 2000 },
  { vendedor: 'Carl', producto: 'A', monto: 800  },
  { vendedor: 'Bob',  producto: 'A', monto: 1200 },
];

// 1. Total por vendedor
const totalPorVendedor = new Map();
for (const { vendedor, monto } of ventas) {
  totalPorVendedor.set(vendedor, (totalPorVendedor.get(vendedor) ?? 0) + monto);
}

// 2. Productos únicos
const productosUnicos = new Set(ventas.map(v => v.producto));

